import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
// [Start Google Fonts Loader]
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// [End Google Fonts Loader]



export type LifeTimelineProps = Record<string, any>;

const LifeTimeline: React.FC<LifeTimelineProps> = ({
  backgroundColor = "#0f172a", // Slate 900
  transparentBackground = false,
  mainText = "if God knows your life from start to end",
  textColor = "#f8fafc", // Slate 50
  barTrackColor = "#334155", // Slate 700
  barFillColor = "#38bdf8", // Sky 400
  durationInSeconds = 10,
  barHeight = 20,
  edgeSoftness = 10,
}) => {
  useFontLoader(["Playfair Display", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animations
  // 1. Text entrance (fade + slight slide up)
  const textEntranceFrame = 0;
  const textOpacity = interpolate(
    frame,
    [textEntranceFrame, textEntranceFrame + 40],
    [0, 1],
    { extrapolateRight: "clamp" }
  );
  const textTranslateY = interpolate(
    frame,
    [textEntranceFrame, textEntranceFrame + 40],
    [20, 0],
    { extrapolateRight: "clamp", easing: (t) => t * (2 - t) } // Ease out
  );

  // 2. Timeline Progress (Linear fill over the duration)
  // We start filling a bit after the text appears
  const startFillFrame = 30;
  // Calculate how many frames we have left to fill
  const fillDuration = Math.max(1, durationInFrames - startFillFrame - 30); // Leave 30 frames buffer at end
  
  const progress = interpolate(
    frame,
    [startFillFrame, startFillFrame + fillDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. Labels fade in
  const labelsOpacity = interpolate(
    frame,
    [startFillFrame - 10, startFillFrame + 10],
    [0, 0.7], // Slightly transparent
    { extrapolateRight: "clamp" }
  );

  // Styles
  const containerStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    backgroundColor: finalBgColor,
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    fontFamily: "Inter, sans-serif",
  };

  const textStyle: React.CSSProperties = {
    fontFamily: "Playfair Display, serif",
    fontSize: Math.min(width, height) * 0.08,
    color: textColor,
    textAlign: "center",
    maxWidth: "80%",
    marginBottom: height * 0.15, // Space between text and bar
    opacity: textOpacity,
    transform: `translateY(${textTranslateY}px)`,
    lineHeight: 1.2,
    textShadow: "0 4px 10px rgba(0,0,0,0.3)",
  };

  const timelineContainerStyle: React.CSSProperties = {
    position: "relative",
    width: "70%",
    height: barHeight,
    display: "flex",
    alignItems: "center",
  };

  const trackStyle: React.CSSProperties = {
    position: "absolute",
    left: 0,
    top: 0,
    width: "100%",
    height: "100%",
    backgroundColor: barTrackColor,
    borderRadius: barHeight / 2,
    overflow: "hidden",
    boxShadow: "inset 0 2px 4px rgba(0,0,0,0.2)",
  };

  const fillStyle: React.CSSProperties = {
    position: "absolute",
    left: 0,
    top: 0,
    height: "100%",
    width: `${progress * 100}%`,
    backgroundColor: barFillColor,
    borderRadius: barHeight / 2,
    boxShadow: `0 0 ${edgeSoftness}px ${barFillColor}`,
    transition: "none", // Critical for Remotion
  };

  const labelStyle: React.CSSProperties = {
    position: "absolute",
    top: barHeight + 15,
    fontSize: Math.min(width, height) * 0.03,
    color: textColor,
    opacity: labelsOpacity,
    fontWeight: 600,
    letterSpacing: "0.05em",
    textTransform: "uppercase",
  };

  const leadingMarkerStyle: React.CSSProperties = {
    position: "absolute",
    left: `${progress * 100}%`,
    top: "50%",
    width: barHeight * 1.5,
    height: barHeight * 1.5,
    borderRadius: "50%",
    backgroundColor: "#fff",
    transform: "translate(-50%, -50%)",
    boxShadow: `0 0 20px ${barFillColor}`,
    opacity: progress > 0 ? 1 : 0, // Visible once progress starts
    transition: "none",
  };

  return (
    <AbsoluteFill style={containerStyle}>
      <h1 style={textStyle}>{mainText}</h1>

      <div style={timelineContainerStyle}>
        {/* Track */}
        <div style={trackStyle}>
          <div style={fillStyle} />
        </div>

        {/* Start Label */}
        <div style={{ ...labelStyle, left: 0 }}>Start</div>

        {/* End Label */}
        <div style={{ ...labelStyle, right: 0 }}>End</div>
        
        {/* Current Position Marker (Soul/Life Force) */}
        {progress > 0 && (
           <div style={leadingMarkerStyle} />
        )}
       
      </div>
    </AbsoluteFill>
  );
};

export default LifeTimeline;